function writeDB(next=db){try{localStorage.setItem(DB_KEY,JSON.stringify(next));db=next;$('#saveIndicator').textContent='● Kaydedildi';return true}catch{toast('Kayıt alanı dolu veya kapalı. Yedek indir.');$('#saveIndicator').textContent='Kayıt yapılamadı';return false}}
function nextRef(){let ref;do{db.counter++;ref='T1-'+new Date().toLocaleDateString('en',{timeZone:'Europe/Istanbul',year:'numeric'})+'-'+String(db.counter).padStart(5,'0')}while(db.declarations.some(d=>d.ref===ref));return ref}
function confirmAction(title,description,fn){$('#confirmTitle').textContent=title;$('#confirmText').textContent=description;$('#confirmYes').onclick=()=>{$('#confirmDialog').close();fn()};$('#confirmDialog').showModal()}
function addRepeat(key,value=''){const row=document.createElement('div');row.className='repeatitem';row.style.cssText='display:flex;gap:8px;margin-bottom:8px';row.innerHTML='<input value="'+esc(value)+'" aria-label="'+(key==='routeCountries'?'Güzergâh ülkesi':'Transit gümrük')+'" '+(key==='routeCountries'?'maxlength="2" autocomplete="off" placeholder="Ülke ara: TR, Türkiye…"':'list="customs"')+'><button type="button" aria-label="Satırı kaldır">×</button>';row.querySelector('button').onclick=()=>{row.remove();queueDraft()};$('[data-repeat="'+key+'"] .repeatrows').append(row);if(key==='routeCountries')attachCombo(row.querySelector('input'),{minChars:1,emptyText:'Ülke bulunamadı.',search:async(q,limit)=>{await operations.ready;const n=normalizeSearch(q),up=q.trim().toUpperCase();return operations.getCountries().filter(c=>!n||c.code===up||normalizeSearch(c.name).includes(n)||c.code.toLowerCase().startsWith(q.trim().toLowerCase())).sort((a,b)=>{const r=c=>c.code===up?0:normalizeSearch(c.name).startsWith(n)?1:2;return r(a)-r(b)}).slice(0,limit)},item:c=>({title:c.code+' – '+c.name}),onPick:c=>{row.querySelector('input').value=c.code;queueDraft()}})}
function readForm(){const v={};for(const [key,,type]of fields){v[key]=type==='checkbox'?form.elements[key].checked:type==='repeat'?[...document.querySelectorAll('[data-repeat="'+key+'"] input')].map(x=>x.value.trim().toUpperCase()).filter(Boolean):form.elements[key].value.trim();if(type==='country')v[key]=v[key].toUpperCase()}return normalizeMeta(v)}
