function queueDraft(){if(!work)return;work.values=readForm();work.status=work.status==='Ön hazırlık'?'Ön hazırlık':'Taslak';renderRail();clearTimeout(draftTimer);draftTimer=setTimeout(flushDraft,250);$('#editorStatus').innerHTML=statusLabel(work.status)}
function flushDraft(){clearTimeout(draftTimer);if(!work)return;work.values=readForm();db.draft={id:work.id,ref:work.ref,values:work.values,records:work.records,step:currentStep,status:work.status,goodDraft:work.goodDraft||null};writeDB()}
function saveWork(status=work?.status||'Taslak',message='Taslak kaydedildi.'){if(!work)return false;clearTimeout(draftTimer);work.values=readForm();const existing=db.declarations.find(d=>d.id===work.id),id=work.id||crypto.randomUUID(),now=new Date().toISOString();const declaration={...existing,...work.values,id,ref:existing?.ref||work.ref||nextRef(),status,createdAt:existing?.createdAt||now,updatedAt:now,archived:existing?.archived||false,activity:[...(existing?.activity||[]),{at:now,message}].slice(-60)};const next={...db,declarations:existing?db.declarations.map(d=>d.id===id?declaration:d):[...db.declarations,declaration],draft:null};const previous=localStorage.getItem(goodsKey(id));try{localStorage.setItem(goodsKey(id),JSON.stringify({name:declaration.ref,records:work.records,draft:{}}));if(!writeDB(next))throw Error('Beyanname kaydedilemedi');work.id=id;work.ref=declaration.ref;work.status=status;location.hash='edit/'+id;$('#editorTitle').textContent=work.ref;$('#editorStatus').innerHTML=statusLabel(status);renderRail();return true}catch{try{if(previous===null)localStorage.removeItem(goodsKey(id));else localStorage.setItem(goodsKey(id),previous)}catch{}toast('Taslak kaydedilemedi. Yedek indirerek mevcut çalışmayı koru.');return false}}
