function startEditor(id=null,step=0,resume=true){clearTimeout(draftTimer);let d=id?db.declarations.find(x=>x.id===id):null;if(id&&!d){showList();return}const draft=resume&&db.draft&&db.draft.id===id?db.draft:null;work={id,ref:d?.ref||draft?.ref||'',status:draft?.status||d?.status||'Taslak',values:normalizeMeta({...defaults,...(d||{}),...(draft?.values||{})}),records:(draft?.records||readGoods(id).records).map(normalizeGood),goodDraft:draft?.goodDraft||null};if(!id&&!draft)work.records=[];fillForm(work.values);currentStep=draft?Math.min(5,Number(draft.step)||0):step;$('#editorTitle').textContent=work.ref||'Yeni T1 Beyannamesi';$('#editorSubtitle').textContent=work.ref?'Bilgilerini güncelle ve kontrol adımlarını tamamla.':'Gümrükten son kontrole, adım adım yazım.';$('#editorStatus').innerHTML=statusLabel(work.status);showView('editor');setStep(currentStep);if(work.goodDraft){setStep(3);openGood(work.goodDraft.editId||null)}location.hash=id?'edit/'+id:'new'}
