function stepComplete(i){if(!work)return false;const v=work.values,issues=allProblems(v,work.records);if(i===5)return work.status==='Kontrol edildi'&&!issues.length;const filled=i===0?!!v.departureOffice&&!!v.arrivalOffice:i===1?!!v.carrier&&(!!v.vehicle||!!v.trailer):i===2?!!v.transportMode:i===3?work.records.length>0:!!v.principal&&!!v.guaranteeType;return filled&&!issues.some(x=>x.step===i)}
function setStep(index){currentStep=Math.max(0,Math.min(5,index));$('#stepper').innerHTML=steps.map((s,i)=>'<button type="button" data-step="'+i+'" class="'+(i===currentStep?'current':stepComplete(i)?'complete':'')+'" '+(i===currentStep?'aria-current="step"':'')+'><b>'+(stepComplete(i)?'✓':i+1)+'</b>'+s.name+'</button>').join('');const s=steps[currentStep];$('#stepEyebrow').textContent='ADIM '+String(currentStep+1).padStart(2,'0');$('#stepTitle').textContent=s.title;$('#stepDescription').textContent=s.description;$('#stepNumber').textContent=(currentStep+1)+' / 6';document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=Number(p.dataset.panel)!==currentStep);$('#goodsStep').hidden=currentStep!==3;$('#reviewStep').hidden=currentStep!==5;$('#previousStep').disabled=currentStep===0;$('#nextStep').hidden=currentStep===5;$('#markReviewed').hidden=currentStep!==5;$('#stepFooter').textContent='Eksik bilgilerle taslak kaydedebilirsin.';$('#stepError').hidden=true;$('#railTipTitle').textContent=s.tipTitle;$('#railTip').textContent=s.tip;renderRail();if(currentStep===3)renderGoods();if(currentStep===5)renderReview();flushDraft()}
