function renderGoods(){const t=totals(work.records);$('#goodsEmpty').hidden=!!t.count;$('#goodsCards').innerHTML=work.records.map((g,i)=>{const issues=goodProblems(g,i);return '<article class="goodcard"><div class="goodcardhead"><div><span class="number">'+String(i+1).padStart(2,'0')+'</span><strong>'+esc(g.mrn||'MRN girilmedi')+'</strong></div><span class="tag '+(issues.length?'warning':'checked')+'">'+(issues.length?issues.length+' kontrol':'Kontrol edildi')+'</span></div><h3>'+esc(g.description||'Ticari tanım girilmedi')+'</h3><p>'+esc(g.sender||'Gönderici eksik')+' → '+esc(g.receiver||'Alıcı eksik')+'<br>GTİP '+esc(g.gtip||'—')+' · '+esc(g.invoice||'Fatura eksik')+'</p><div class="goodcardfooter"><span>'+fmt(num(g.gross)||0)+' kg brüt · '+fmt(num(g.net)||0)+' kg net · '+fmt(num(g.packages)||0)+' kap</span><div><button type="button" data-good="edit" data-id="'+g.id+'">Düzenle</button><button type="button" data-good="hat" data-id="'+g.id+'" title="Bu kalem için hat bildirimi (TCGB hazır) kaydı aç">Hat bildirimi</button><button type="button" data-good="clone" data-id="'+g.id+'" title="Aynı plakaya ek kayıt aç">Ek kayıt</button><button type="button" data-good="up" data-id="'+g.id+'" aria-label="Eşya satırını yukarı taşı" '+(i===0?'disabled':'')+'>↑</button><button type="button" data-good="down" data-id="'+g.id+'" aria-label="Eşya satırını aşağı taşı" '+(i===work.records.length-1?'disabled':'')+'>↓</button><button type="button" data-good="remove" data-id="'+g.id+'">Sil</button></div></div></article>'}).join('');$('#goodsTotals').innerHTML='<span><strong>'+t.count+'</strong>eşya satırı</span><span><strong>'+fmt(t.gross)+'</strong>kg brüt</span><span><strong>'+fmt(t.net)+'</strong>kg net</span><span><strong>'+fmt(t.packages)+'</strong>kap</span>'}
