async function parseFile(file){if(file.size>30*1024*1024)throw Error('Dosya 30 MB altında olmalı.');if(file.name.toLowerCase().endsWith('.xlsx'))return {records:readExcel(new Uint8Array(await file.arrayBuffer()))};return JSON.parse(await file.text())}
$('#goodsImport').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const v=await parseFile(f),records=v.records||v.goods;if(!Array.isArray(records))throw Error('Dosyada eşya satırı bulunamadı.');let added=0;for(const value of records){const g=normalizeGood(value);if(!g.mrn||work.records.some(x=>x.mrn===g.mrn))continue;g.id=crypto.randomUUID();g.reviewed=false;work.records.push(g);added++}work.status='Taslak';flushDraft();renderGoods();renderRail();toast(added+' tekil eşya satırı eklendi. Belge karşılaştırması yap.')}catch(err){toast('İçe alınamadı: '+err.message)}finally{e.target.value=''}};
function importRecords(records,name){const id=crypto.randomUUID(),ref=nextRef(),now=new Date().toISOString(),seen=new Set();const goods=records.filter(x=>x&&typeof x==='object').map(normalizeGood).filter(g=>{if(!g.mrn||seen.has(g.mrn))return false;seen.add(g.mrn);return true}).map(g=>({...g,id:crypto.randomUUID(),reviewed:false}));if(!goods.length)throw Error('Dosyada tekil ihracat MRN bulunamadı.');const declaration={...normalizeMeta(defaults),id,ref,status:'Ön hazırlık',customer:text(name),createdAt:now,updatedAt:now,activity:[{at:now,message:'Eşya kayıtları içe aktarıldı.'}]};localStorage.setItem(goodsKey(id),JSON.stringify({name:ref,records:goods}));db.declarations.push(declaration);writeDB();return id}
$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const v=await parseFile(f);if(v.format==='t1-ncts'&&Array.isArray(v.db?.declarations)){let added=0;for(const value of v.db.declarations){if(!value?.id||!Array.isArray(v.goods?.[value.id]?.records))continue;if(db.declarations.some(d=>d.id===value.id||d.sourceBackupId===value.id))continue;const id=crypto.randomUUID(),now=new Date().toISOString();let ref=text(value.ref)||nextRef();if(db.declarations.some(d=>d.ref===ref))ref=nextRef();const d={...normalizeMeta(value),id,ref,sourceBackupId:value.id,status:'Ön hazırlık',archived:!!value.archived,createdAt:Number.isFinite(Date.parse(value.createdAt))?value.createdAt:now,updatedAt:now,activity:[{at:now,message:'Yedekten içe aktarıldı; yeniden kontrol bekliyor.'}]};localStorage.setItem(goodsKey(id),JSON.stringify({name:ref,records:v.goods[value.id].records.map(normalizeGood).map(g=>({...g,id:crypto.randomUUID(),reviewed:false}))}));db.declarations.push(d);added++}if(Array.isArray(v.companies))await references.importRecords(v.companies);if(v.plateCountries)await operations.restorePlateCountries(v.plateCountries);if(v.accounting)accounting.importData(v.accounting);if(v.ens)ens.importData(v.ens);if(Array.isArray(v.plates))await plates.importData(v.plates);if(Array.isArray(v.hat))hat.importData(v.hat);db.counter=Math.max(db.counter,Number(v.db.counter)||0);if(v.db.draft&&!db.draft){const draft=v.db.draft;db.draft={id:null,ref:'',values:normalizeMeta(draft.values),records:Array.isArray(draft.records)?draft.records.map(normalizeGood).map(g=>({...g,reviewed:false})):[],step:Math.max(0,Math.min(5,Number(draft.step)||0)),status:'Ön hazırlık',goodDraft:draft.goodDraft?{editId:draft.goodDraft.editId||null,values:{...normalizeGood(draft.goodDraft.values),reviewed:false}}:null}}writeDB();renderList();toast(added+' beyanname içe alındı.')}else if(v.format==='t1-preparation'&&Array.isArray(v.goods)){const id=importRecords(v.goods,v.declaration?.customer||f.name),d=db.declarations.find(x=>x.id===id);Object.assign(d,normalizeMeta(v.declaration));writeDB();startEditor(id,5,false)}else if(Array.isArray(v.records)){startEditor(importRecords(v.records,v.name||f.name),5,false)}else throw Error('T1 yedek veya PCS Excel dosyası seç.')}catch(err){toast('İçe alınamadı: '+err.message)}finally{e.target.value=''}};
$('#previewPrint').onclick=()=>{work.values=readForm();const d=work.values;$('#printArea').innerHTML='<h1>'+esc(work.ref||'Taslak')+' · T1 hazırlık formu</h1><div class="printgrid">'+groups.map(([title,fs])=>'<section><h2>'+title+'</h2>'+fs.map(([key,label,type])=>'<p><b>'+esc(label)+':</b> '+esc(type==='checkbox'?(d[key]?'Evet':'Hayır'):Array.isArray(d[key])?d[key].join(' → '):d[key]||'—')+'</p>').join('')+'</section>').join('')+'</div><h2>Eşya bilgileri</h2><table><tr><th>MRN / GTİP</th><th>Tanım / Firmalar</th><th>Brüt / Net / Kap</th><th>Fatura</th></tr>'+work.records.map(g=>'<tr><td>'+esc(g.mrn)+'<br>'+esc(g.gtip)+'</td><td>'+esc(g.description)+'<br>'+esc(g.sender)+' → '+esc(g.receiver)+'</td><td>'+esc(g.gross)+' / '+esc(g.net)+' / '+esc(g.packages)+'</td><td>'+esc(g.invoice)+'<br>'+esc(g.invoiceDate)+'<br>'+esc(g.amount)+' '+esc(g.currency)+'</td></tr>').join('')+'</table><p>Hazırlık formudur. Resmî tescil veya transit refakat belgesi değildir.</p>';window.print()};
if(!localStorage.getItem('t1-v2-migrated')){try{const legacy=JSON.parse(localStorage.getItem('t1-atolye-v1'));if(legacy?.records?.length)importRecords(legacy.records,legacy.name||'Önceki çalışma');localStorage.setItem('t1-v2-migrated','1')}catch{}}
let checksChanged=false;for(const d of db.declarations){if(d.status==='Kontrol edildi'&&allProblems(d,readGoods(d.id).records).length){d.status='Taslak';checksChanged=true}}if(checksChanged)writeDB();
function showEns(id){if(work)flushDraft();work=null;showView('ens');ens.show(id);location.hash=id?'ens/'+id:'ens'}
function showAccounting(){if(work)flushDraft();work=null;showView('accounting');accounting.render();location.hash='accounting'}
function showList2(name){if(work)flushDraft();work=null;showView(name);lists.render(name);location.hash=name}
function showHat(){if(work)flushDraft();work=null;showView('hat');hat.show();location.hash='hat'}
function showReferences(){if(work)flushDraft();work=null;showView('references');location.hash='references'}
let plateLookup=()=>null;
const operations=installOperations({form,changed:queueDraft,toast,lookupPlate:(p,k)=>plateLookup(p,k)});
const references=installReferences({form,goodForm,metaChanged:queueDraft,goodChanged:saveGoodDraft,showReferences,toast});
const plates=installPlates({toast});plateLookup=plates.lookup;
const ROUTES=[['H.BEYLİ / TR-BG-RS-HR-SI','TR221300',['TR','BG','RS','HR','SI']],['K.KULE / TR-BG-RS-HR-SI','TR220200',['TR','BG','RS','HR','SI']],['K.KULE / TR-BG-RO-HU','TR220200',['TR','BG','RO','HU']],['K.KULE / TR-BG-RS-HU','TR220200',['TR','BG','RS','HU']],['H.BEYLİ / TR-BG-RO-HU','TR221300',['TR','BG','RO','HU']],['DEREKÖY / TR-BG-RO-HU','TR220800',['TR','BG','RO','HU']],['İPSALA / TR-GR-IT','TR220500',['TR','GR','IT']],['Sadece TR (rotayı temizle)','',['TR']]];
{const host=$('[data-repeat="routeCountries"]');if(host){const bar=document.createElement('div');bar.className='routePreset';bar.innerHTML='<label>Hazır rota seç <select aria-label="Hazır rota"><option value="">Rota seçiniz…</option>'+ROUTES.map((r,i)=>'<option value="'+i+'">'+esc(r[0])+'</option>').join('')+'</select></label><small>Sınır gümrüğünü ve güzergâh ülkelerini birlikte doldurur; sonra elle değiştirebilirsin.</small>';host.prepend(bar);bar.querySelector('select').onchange=async e=>{const r=ROUTES[e.target.value];if(!r)return;await operations.ready;if(r[1])operations.setBorder(r[1]);host.querySelector('.repeatrows').innerHTML='';for(const c of r[2])addRepeat('routeCountries',c);queueDraft();e.target.value='';toast('Rota dolduruldu: '+r[2].join(' → ')+(r[1]?' · sınır gümrüğü '+r[1]:''))}}}
const hat=installHat({toast,confirmAction});$('#navHat').onclick=showHat;
const lists=installLists({references,plates,toast,confirmAction,show:showList2});
for(const [name,kind] of [['vehicle','motor'],['trailer','trailer'],['borderVehicle',null]]){const input=form.elements[name];if(input)plates.attachField(input,{kind,onPick:r=>{input.value=r.plate;const c=form.elements[name+'Country'];if(c&&r.country)c.value=r.country;if(name==='vehicle'&&r.owner&&form.elements.carrier)references.pickCarrier(r.owner);queueDraft()}})}
const ens=installEns({lookupPlate:plates.lookup,attachPlate:plates.attachField,navigate:showEns,toast,confirmAction,getCompanies:()=>references.getCompanies(),getDeclarations:()=>db.declarations,getGoods:id=>readGoods(id).records,knownPlates:()=>operations.getPlateCountries()});
const accounting=installAccounting({showAccounting,toast,confirmAction,getDeclarations:()=>[...db.declarations,...ens.asDeclarations()],getCompanies:()=>references.getCompanies()});
ens.setInvoiceHook(r=>accounting.openInvoiceForDeclaration({ref:r.ref,customer:r.customer||r.consignee,vehicle:r.vehicle},{service:/ens/i,label:'ENS beyannamesi hizmet bedeli'}));
function route(){const h=location.hash.slice(1);if(h==='new')startEditor(null,0,true);else if(h.startsWith('edit/'))startEditor(h.slice(5),0,true);else if(h.startsWith('declaration/'))startEditor(h.slice(12),5,true);else if(h==='connection')showConnection();else if(h==='references')showReferences();else if(h==='companies'||h==='vehicles')showList2(h);else if(h==='hat')showHat();else if(h==='accounting')showAccounting();else if(h==='ens')showEns(null);else if(h.startsWith('ens/'))showEns(h.slice(4));else showList()}
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h==='list'&&!$('#listView').hidden||h==='connection'&&!$('#connectionView').hidden||h==='references'&&!$('#referencesView').hidden||(h==='companies'||h==='vehicles')&&!$('#'+h+'View').hidden||h==='new'&&!$('#editorView').hidden&&!work?.id||h==='edit/'+work?.id&&!$('#editorView').hidden)return;route()});window.addEventListener('beforeunload',()=>{if(work)flushDraft()});route();
